H.background();
const v = H.plot2d({ xMin: 0, xMax: 10, yMin: -2.5, yMax: 2.5 });
v.grid(); v.axes();
const freq = Math.max(0.1, P.f), lambda = Math.max(0.3, P.lambda), A = Math.max(0.1, P.A);
const speed = freq * lambda; // v = f * lambda
const k = 2 * Math.PI / lambda, omega = 2 * Math.PI * freq;
// The traveling wave itself.
v.fn(x => A * Math.sin(k * x - omega * t), { color: H.colors.accent, width: 3 });
// Track one crest as it moves at speed v; wrap it across the SAME window.
// A crest of A*sin(k x - w t) sits where k x - w t = pi/2, i.e. x = lambda/4 + speed*t,
// so the dot rides exactly on the drawn wave's crest (y = A) at every frame.
const span = 10;
const crestX = ((lambda / 4 + speed * t) % span + span) % span;
v.dot(crestX, A, { r: 6 + Math.sin(t * 3), fill: H.colors.warn });
// Velocity arrow on the crest showing direction + magnitude of propagation.
const arrowLen = Math.min(2.5, speed * 0.4);
v.arrow(crestX, A, Math.min(9.5, crestX + arrowLen), A, { color: H.colors.good, width: 2.5 });
v.text("v", Math.min(9.4, crestX + arrowLen * 0.5), A + 0.45, { color: H.colors.good, size: 13 });
// One wavelength bracket near the bottom.
v.arrow(1, -2.1, 1 + lambda, -2.1, { color: H.colors.violet, width: 2 });
v.arrow(1 + lambda, -2.1, 1, -2.1, { color: H.colors.violet, width: 2 });
v.text("lambda", 1 + lambda * 0.5 - 0.2, -1.7, { color: H.colors.violet, size: 12 });
H.text("Wave speed:  v = f * lambda", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("f = " + freq.toFixed(1) + " Hz   lambda = " + lambda.toFixed(1) + " m   ->   v = " + speed.toFixed(2) + " m/s   (crest moves one lambda per period)", 24, 52, { color: H.colors.sub, size: 12 });
H.legend([{ label: "wave", color: H.colors.accent }, { label: "crest", color: H.colors.warn }, { label: "v = f lambda", color: H.colors.good }], H.W - 170, 28);
